import java.util.*;

class Solution {
  public int assignBikes(int[][] workers, int[][] bikes) {
    int n = workers.length, m = bikes.length;
    int[] dp = new int[1 << m]; // dp[mask]: least cost giving the first bitCount(mask) workers the bikes in mask
    Arrays.fill(dp, Integer.MAX_VALUE);
    dp[0] = 0;
    int best = Integer.MAX_VALUE;
    for (int mask = 0; mask < (1 << m); mask++) {
      if (dp[mask] == Integer.MAX_VALUE) continue;
      int w = Integer.bitCount(mask);
      if (w == n) {
        best = Math.min(best, dp[mask]);
        continue;
      }
      for (int b = 0; b < m; b++) {
        if ((mask >> b & 1) != 0) continue;
        int d = Math.abs(workers[w][0] - bikes[b][0]) + Math.abs(workers[w][1] - bikes[b][1]);
        dp[mask | 1 << b] = Math.min(dp[mask | 1 << b], dp[mask] + d);
      }
    }
    return best;
  }
}
